from datetime import datetime, timedelta
from funcy import cache, reraise, SkipMemoization

calls = []
@cache(60, key_func=lambda x: x)
def cached(x):
    calls.append(x)
    if x < 0:
        raise cached.skip('skipped')
    if x == 0:
        raise cached.skip()
    return x * 2
assert cached.skip is SkipMemoization
assert cached.memory == {}
assert cached(2) == cached(2) == 4
assert calls == [2]
assert cached.memory[2][0] == 4
cached.memory.clear()
assert cached(2) == 4 and calls == [2, 2]
cached.memory[2] = (8, datetime.now())
assert cached(2) == 8
cached.memory[2] = (8, datetime.now() - timedelta(seconds=61))
assert cached(2) == 4
assert cached(-1) == cached(-1) == 'skipped'
assert cached(0) is None and -1 not in cached.memory and 0 not in cached.memory
cached.invalidate(2)
assert 2 not in cached.memory
cached(2)
cached.invalidate_all()
assert not cached.memory

original = ValueError('original')
seen = []
def transform(error):
    seen.append(error)
    return RuntimeError('converted: ' + str(error))
@reraise(ValueError, transform)
def fail():
    raise original
for run in (fail,):
    try:
        run()
    except RuntimeError as error:
        assert str(error) == 'converted: original'
        assert error.__cause__ is original
    else:
        raise AssertionError('did not raise')
assert seen == [original]
class CallableError(Exception):
    def __call__(self, error):
        raise AssertionError('exception instance must not be called')
for target in (RuntimeError, RuntimeError('fixed'), CallableError('callable')):
    try:
        with reraise([ValueError], target):
            raise original
    except type(target) if isinstance(target, BaseException) else target as error:
        assert error.__cause__ is original
        if isinstance(target, BaseException):
            assert error is target
        else:
            assert error.args == ()
with reraise(ValueError, transform):
    pass
assert seen == [original]
print('Targeted cache and reraise checks passed')
